%[text] %[text:anchor:H_27BA47A5] # **Generation of a biquadratic quadrilateral mesh**
%[text] It returnd a biquadratic quadrilateral mesh based on a provided bilinear quadrilateral mesh:
%[text]{"align":"center"} ![biquadratic_mesh.png](text:image:398d)
%[text:tableOfContents]{"heading":"**Table of Contents**"}
function [mshQ2, biasX] = generateBiquadraticQuadrilateralMesh ...
    (numElx, numEly, nodesX, nodesY, mshQ1, numNodesElQ1, numNodesElQ2)
%[text] %[text:anchor:H_B24D241A] ## **Function Description**
%[text] It returns a mesh corresponding to biquadratic quadrilateral elements.
%[text] %[text:anchor:H_C2A6403E]  **Input :**
%[text]  `numElx`, `numEly` : Number of elements along the $X${"editStyle":"visual"}- and the $Y${"editStyle":"visual"}-directions
%[text]  `nodesX`, `nodesY` : $X${"editStyle":"visual"}- and $Y${"editStyle":"visual"}-Cartesian coordinates of the nodes in the mesh
%[text]  `numNodesEl` : Number of nodes per bilinear quadrilateral element
%[text]  `mshQ1` : Structure containing the nodes and elements of the bilinear quadrilateral mesh onto which the biquadratic bilinear mesh is created
%[text]                                  .nodes : Array containing the Cartesian coordinates of the nodes in the mesh
%[text]                             .elements : Array containing the node IDs per element in the mesh
%[text]  `numNodesElQ1` : Number of nodes per bilinear quadrilateral element
%[text]  `numNodesElQ2` : Number of nodes per biquadratic quadrilateral element
%[text] %[text:anchor:H_CBAFD59D]  **Output :**
%[text]  `mshQ2` : Structure containing the nodes and elements of the biquadratic quadrilateral mesh
%[text]                                 .`nodes` : Array containing the Cartesian coordinates of the nodes in the mesh
%[text]                            .`elements` : Array containing the node IDs per element in the mesh
%[text]  `biasX` : Number of nodes of the background bilinear quadrilateral mesh and the set of intermediate for each edge along the y-direction
%[text] %[text:anchor:H_D38286BD] ## **Function Implementation**
%[text] %[text:anchor:H_7F668BED] ### **Input validation**
arguments
    numElx (1, 1) double {mustBeInteger, mustBePositive}
    numEly (1, 1) double {mustBeInteger, mustBePositive}
    nodesX (:, :) double
    nodesY (:, 1) double {mustHaveEqualNumberOfElements(nodesY, nodesX)}
    mshQ1 (1, 1) {mustHaveNodesAndElements}
    numNodesElQ1 (1, 1) double {mustBeInteger, mustBePositive}
    numNodesElQ2 (1, 1) double {mustBeInteger, mustBePositive}
end
%[text] %[text:anchor:H_CB359BF8] ### Intermediate boundary nodes along the *Y*-direction
nodesY_reshaped = reshape(nodesY, numEly + 1, numElx + 1);
nodes_Q2_Y_x = zeros(numEly, numElx + 1, "like", nodesX);
nodes_Q2_Y_y = zeros(numEly, numElx + 1, "like", nodesX);
for ii = 1:numEly
    for jj = 1:numElx + 1
        nodes_Q2_Y_x(ii, jj) = mean(nodesX(ii:ii + 1, jj));
        nodes_Q2_Y_y(ii, jj) = mean(nodesY_reshaped(ii:ii + 1, jj));
    end
end
%[text] %[text:anchor:H_E6C6BFDB] #### Adding the nodal coordinates to `mesh.nodes`
bias_Y = numel(mshQ1.nodes(:, 1));
mshQ2.nodes = [mshQ1.nodes; [nodes_Q2_Y_x(:) nodes_Q2_Y_y(:) zeros(numEly*(numElx + 1), 1)]];
%[text] %[text:anchor:H_2E8CBC67] #### Adding the element connectivity to `mesh.elements`
mshQ2.elements = zeros(length(mshQ1.elements(:, 1)), numNodesElQ2);
mshQ2.elements(:, 1:numNodesElQ1) = mshQ1.elements;
counterEl = 1;
for ii = 1:numElx
    adv = (ii - 1)*numEly + bias_Y;
    advplus1 = ii*numEly + bias_Y;
    for jj = 1:numEly
        mshQ2.elements(counterEl, numNodesElQ1 + 1:numNodesElQ1 + 2) = [jj+adv jj+advplus1];
        counterEl = counterEl + 1;
    end
end
%[text] %[text:anchor:H_F399F54E] ### Intermediate boundary nodes along the *X*-direction
nodes_Q2_X_x = zeros(numEly + 1, numElx, "like", nodesX);
nodes_Q2_X_y = zeros(numEly + 1, numElx, "like", nodesX);
for ii = 1:numEly + 1
    for jj = 1:numElx
        nodes_Q2_X_x(ii, jj) = mean(nodesX(ii, jj:jj + 1));
        nodes_Q2_X_y(ii, jj) = mean(nodesY_reshaped(ii, jj:jj + 1));
    end
end
%[text] %[text:anchor:H_1AEA8EEE] #### Adding the nodal coordinates to `mesh.nodes`
biasX = numel(mshQ2.nodes(:, 1));
mshQ2.nodes = [mshQ2.nodes; [nodes_Q2_X_x(:) nodes_Q2_X_y(:) zeros((numEly + 1)*numElx, 1)]];
%[text] %[text:anchor:H_DE912E94] #### Adding the element connectivity to `mesh.elements`
counterEl = 1;
for ii = 1:numElx
    for jj = 1:numEly
        adv = (ii - 1)*(numEly + 1) + jj + biasX;
        mshQ2.elements(counterEl, numNodesElQ1 + 3:numNodesElQ1 + 4) = [adv adv+1];
        counterEl = counterEl + 1;
    end
end
%[text] %[text:anchor:H_A049B3CE] ### Middle nodes
bias = numel(mshQ2.nodes(:, 1));
for ii = 1:numel(mshQ1.elements(:, 1))
    barycenter =  mean(mshQ2.nodes(mshQ2.elements(ii, 1:4),:), 1);
    mshQ2.nodes = [mshQ2.nodes; barycenter];
    mshQ2.elements(ii, end) = ii + bias;
end
%[text] 
end

